package ca.humber.alerts;import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.LocalDateTime;@Entity public class Alert {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@NotBlank @Size(max=250) public String message;@NotBlank @Pattern(regexp="INFO|WARNING|CRITICAL") public String severity;@NotBlank @Pattern(regexp="OPEN|ACKNOWLEDGED|RESOLVED") public String status;public LocalDateTime createdAt=LocalDateTime.now();}